// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // newOwner is the candidate new owner, fuzzed
        vm.assume(newOwner != address(0));
        // The reference owner must be the deployer (this test contract)
        // The buggy owner is hardcoded to 0x0000000000000000000000000000000000000001
        // transferOwnership is onlyOwner, so calling it as the deployer should succeed in reference,
        // but in the buggy version, owner() is 0x...01, so only the hardcoded address can call onlyOwner functions.
        // We prank as the hardcoded address: this will succeed in the buggy version (owner() == pranked address),
        // but revert in the reference (owner() != pranked address).
        address hardcodedOwner = address(0x0000000000000000000000000000000000000001);
        vm.prank(hardcodedOwner);
        try c.transferOwnership(newOwner) returns (bool) {
            // If it didn't revert, the buggy version succeeded
            assertTrue(false);
        } catch {
            // If it reverted, the reference behavior is correct
            assertTrue(true);
        }
    }
}

